li.OKResult:
	local nR = world:RandomInt(50,70)
	me:AddMsg(string.format(XT("[NAME]趁各路大仙争吵之际悄悄偷走了魔石，突有一位散仙发现了你的动机大叫了起来，在场所有人纷纷冷眼相对，[NAME]拿起石头转身就跑。"), tostring(nR)));
	for i = 1, nR do
		me:AddEnemy(world:RandomInt(1,7),world:RandomFloat(0,1));
	end
me:DropAwardItem("Item_LYGY",1);				
me:AddMsg("恭喜你得到江湖至宝，但我不得不提醒你，你还是快跑吧宝贝，把东西带在身上，让所有人离开。");
story:FinishSecret();

	local nR = world:RandomInt(30,50)
	me:AddMsg(string.format(XT("[NAME]抢完四剑转身就跑，各路散仙追至而来。"), tostring(nR)));
	for i = 1, nR do
		me:AddEnemy(world:RandomInt(1,5),world:RandomFloat(0,1));
	end
me:DropAwardItem("Item_MiBao_ZhuXianJian",1);me:DropAwardItem("Item_MiBao_LuXianJian",1);me:DropAwardItem("Item_MiBao_JueXianJian",1);me:DropAwardItem("Item_MiBao_XianXianJian",1);
me:AddMsg("江湖中人也听闻[NAME]的门派抢到了诛仙四剑，纷纷接踵而至。");
me:AddMsg("你的门派将受到大量敌人袭击。");
story:FinishSecret();

if world:GetWorldFlag(39) == 0 then
me:AddMsg(XT("[NAME]尝试用神念靠近裂缝，裂缝中突然传来一阵可怕的吸力，将[NAME]的意识卷入其中。在经过一个光怪陆离的通道后，[NAME]来到一个陌生的世界。"));me:TriggerStory("Secrets_YiJieKaiQi11");
	else
		me:AddMsg(XT("你已经探访过这里了。"));
	end


if world:GetWorldFlag(87) == 0 then
me:AddMsg(XT("[NAME]尝试用神念靠近裂缝，裂缝中突然传来一阵可怕的吸力，将[NAME]的意识卷入其中。在经过一个光怪陆离的通道后，[NAME]来到一个陌生的世界。"));me:TriggerStory("Secrets_YiJieKaiQi21");
